import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

const yaml = `---
- 0b1010
- 0o777
- 0x1F
- 0
- 12345
`;

describe('proof', () => {
  it('fails on the patched build', () => {
    const obj = load(yaml);
    assert.deepEqual(obj, [10, 511, 31, 0, 12345]);
    assert.equal(dump(obj), yaml);
  });
});

